@Test
public void testPlusMonthsZero() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(0);
    assertEquals("2023-10-05", result.toString());
}

@Test
public void testPlusMonthsPositiveOneMonth() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(1);
    assertEquals("2023-11-05", result.toString());
}

@Test
public void testPlusMonthsNegativeOneMonth() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(-1);
    assertEquals("2023-09-05", result.toString());
}

@Test
public void testPlusMonthsEndOfMonthClamp() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 31);
    LocalDate result = date.plusMonths(1);
    assertEquals("2024-01-31", result.toString());
}

@Test
public void testPlusMonthsLargePositiveDelta() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(1200);
    assertEquals("2123-10-05", result.toString());
}

@Test
public void testPlusMonthsLargeNegativeDelta() throws Exception {
    LocalDate date = new LocalDate(2023, 10, 5);
    LocalDate result = date.plusMonths(-1200);
    assertEquals("1923-10-05", result.toString());
}

@Test
public void testPlusMonthsMaxYear() throws Exception {
    LocalDate date = new LocalDate(2100, 12, 31);
    LocalDate result = date.plusMonths(1);
    assertEquals("2101-01-31", result.toString());
}

@Test
public void testPlusMonthsMinYear() throws Exception {
    LocalDate date = new LocalDate(1900, 1, 1);
    LocalDate result = date.plusMonths(-1);
    assertEquals("1899-12-01", result.toString());
}
